export function t(key, lang = 'tr', vars) {
  const entry = UI[key];
  let str = (entry && (entry[lang] || entry.en)) || key;
  if (vars) Object.keys(vars).forEach((k) => { str = str.replace(`{${k}}`, vars[k]); });
  return str;
}
